mapper.select:


     and mun.user_id = #{userId}
     and mun.notice_type = #{noticeType}
     and mun.read_flag = #{readFlag}
     and mun.title like concat('%', #{title}, '%')

        and mun.create_time >= #{params.beginTime}


        and mun.create_time <= concat(#{params.endTime}, ' 23:59:59')


order by mun.create_time desc, mun.id desc
